import {GENES,TRAIT_INDEX,TRAITS} from './biology.js';
import {SHAPE_GENES,bodyReport} from './development.js';
import {escape} from './views.js';
import {COMPARISON_CHANGES,summarizeComparisons} from './comparison.js';

const number=(value,digits=2)=>(Number(value)===0?0:Number(value)).toLocaleString('zh-CN',{maximumFractionDigits:digits});
const modeNames={founder:'初始复制者',sexual:'双亲交叉',asexual:'单亲复制'};
const breedingNames={sexual:'有性繁殖',asexual:'无性繁殖',facultative:'兼性繁殖'};
const archiveSearch=()=>`<form id="find-individual-form" class="archive-search"><label for="individual-search">查找个体</label><input id="individual-search" aria-label="个体编号" type="number" min="1" step="1" placeholder="编号" required><button class="button subtle" type="submit">查看 ↗</button></form>`;

export function individualCard(record,label='观测个体'){
 return `<button class="relative-card" data-observe="${record.id}"><span>${label} <b>#${record.id}</b></span><span class="specimen-window" data-individual="${record.id}" data-fixed-view="true"></span><small>G${record.generation} · ${record.traits.length} 项结构 · ${record.death?'历史标本':'存活'}</small></button>`;
}

function inheritanceTable(rows,names){
 return `<div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>性状</th><th>遗传来源</th><th>来源值</th><th>出生值</th><th>出生时变异</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(typeof names[r.index]==='string'?names[r.index]:names[r.index].name)}</td><td><button class="text-button" data-observe="${r.parent}">#${r.parent} ↗</button></td><td>${number(r.before*100,1)}</td><td>${number(r.after*100,1)}</td><td>${r.mutated?'记录到突变':'—'}</td></tr>`).join('')}</tbody></table></div>`;
}

function distribution(world,record,index){
 const group=world.agents.filter(a=>a.origin===record.origin),bins=Array(12).fill(0);
 group.forEach(a=>bins[Math.min(11,Math.floor(a.shape[index]*12))]++);
 const max=Math.max(1,...bins),position=record.shape[index]*100;
 return `<div class="trait-distribution"><div><span>${SHAPE_GENES[index]}</span><b>${number(position,1)}</b></div><div class="distribution-bars" role="img" aria-label="${SHAPE_GENES[index]}，同源存活个体分布；所选个体 ${number(position,1)}">${bins.map(n=>`<i style="height:${n/max*100}%" title="${n} 个体"></i>`).join('')}<em style="left:${Math.min(99,position)}%"></em></div><div><small>0</small><small>100</small></div></div>`;
}

export function observationView(world,id,comparisonId,region='body',size='equal'){
 const record=world.records[id];
 if(!record){
  const samples=world.species.filter(s=>s.count&&s.specimen).slice(0,6).map(s=>world.records[s.specimen.id]);
  return `<div class="view-intro"><div><span class="eyebrow">INDIVIDUAL / KIN / HISTORY</span><h2>每一种形状，都有来处</h2><p>从地图选中一个生命，或从这些真实个体开始。它的身体、父母和后代会留在同一份档案里。</p></div></div>${archiveSearch()}<div class="relative-grid">${samples.map(r=>individualCard(r)).join('')||'<p class="empty-copy">等待第一批生命出现。</p>'}</div>`;
 }
 const live=world.agents.find(a=>a.id===record.id),energy=live?live.energyLedger:record.energy;
 const reports=bodyReport(record),report=reports.find(r=>r.id===region),other=world.records[comparisonId];
 const parents=record.parents.map(id=>world.records[id]),children=record.offspring.map(id=>world.records[id]);
 const livingChildren=children.filter(r=>!r.death).length,age=(record.death?record.death.tick:world.tick)-record.born;
 const species=world.species.find(s=>s.id===(live?live.species:record.birthSpecies));
 const observedUntil=record.death?record.death.tick:world.tick;
 const originGroup=world.agents.filter(a=>a.origin===record.origin),alleleA=originGroup.filter(a=>a.neutralAllele===0).length;
 const energyNames={intake:'累计摄入',maintenance:'身体维护',movement:'运动支出',reproduction:'繁殖投入',hunting:'捕食支出',stress:'环境压力'};
 const traitsAdded=other?record.traits.filter(t=>!other.traits.includes(t)):[],traitsLost=other?other.traits.filter(t=>!record.traits.includes(t)):[];
 return `<div class="view-intro"><div><span class="eyebrow">LIFE ARCHIVE · ${record.death?'PRESERVED':'OBSERVING'}</span><h2>个体 #${record.id} <span class="individual-status ${record.death?'ended':''}">${record.death?'历史标本':'持续追踪'}</span></h2><p>${live?'当前分群':'出生分群'}：${escape(species.name)} · 出生于 T + ${record.born} · 第 ${record.generation} 代 · ${modeNames[record.mode]}</p></div><button class="button subtle" data-locate="${record.id}">${live?'回到生态现场 ↗':'查看历史事件 ↗'}</button></div>
 ${archiveSearch()}<section class="organism-observatory"><div class="organism-display"><div class="specimen-window individual-model" data-individual="${record.id}" data-region="${region}" data-fixed-view="true"><span class="specimen-stage">${record.death?'保存的出生形态':'所选个体 · 身体结构'} / #${record.id}</span><span class="specimen-scale">出生结构重建 · 等大展示</span></div><div class="body-regions" role="group" aria-label="观察身体部位">${reports.map(r=>`<button data-region="${r.id}" class="${r.id===region?'active':''}" aria-pressed="${r.id===region}">${r.name}</button>`).join('')}</div></div>
 <aside class="body-reading"><span class="eyebrow">STRUCTURE / FUNCTION</span><h3>${report.name}</h3><p>${report.summary}</p><dl class="body-metrics">${report.metrics.map(m=>`<div><dt>${m.label}</dt><dd>${number(m.value)}<small>${m.unit}</small></dd></div>`).join('')}<div><dt>几何维护基础项</dt><dd>${number(report.cost,5)}<small>/ 时步</small></dd></div></dl><p class="model-assumption">${report.note} 维护基础项还会乘体量与休眠修正；实际支出见下方账目。</p><div class="body-traits">${record.traits.map(id=>`<button data-explore="${id}">${TRAITS[TRAIT_INDEX[id]].name}</button>`).join('')||'<span>原始复制结构</span>'}</div></aside></section>
 <div class="individual-facts"><article><span>已观察生命时长</span><strong>${age}<small> 时步</small></strong><small>${record.death?`T + ${record.death.tick} · ${record.death.cause}`:'仍在存活，生命周期尚未结束'}</small></article><article><span>直接后代</span><strong>${children.length}<small> / ${livingChildren} 存活</small></strong><small>出生至当前 T + ${world.tick} 的记录</small></article><article><span>繁殖方式</span><strong class="word-value">${breedingNames[record.reproduction.mode]}</strong><small>起源体系 ${record.origin} · 身份固定</small></article></div>
 <section class="archive-panel"><div class="section-heading"><h2>身体的异同</h2><div class="size-options" role="group" aria-label="标本比较比例"><button data-size="equal" class="${size==='equal'?'active':''}">等大观察</button><button data-size="relative" class="${size==='relative'?'active':''}">同一比例</button></div></div><p>${other?`与 ${parents.some(p=>p.id===other.id)?'亲本':'同源个体'} #${other.id} 对照。`:'尚无可比较个体。'}${size==='relative'?'模型使用相同观察比例，可比较身体尺度。':'分别适配观察窗口，适合比较结构，不表示真实体型相同。'}视角和光照保持一致。</p>
 ${other?`<div class="specimen-comparison"><article><header><span>${parents.some(p=>p.id===other.id)?'亲本':'同源对照'} #${other.id}</span><button class="text-button" data-observe="${other.id}">查看来源 ↗</button></header><div class="specimen-window" data-individual="${other.id}" data-fixed-view="true" data-size="${size}"></div><small>G${other.generation} · ${other.traits.length} 项结构</small></article><article><header><span>所选个体 #${record.id}</span><span>G${record.generation}</span></header><div class="specimen-window" data-individual="${record.id}" data-fixed-view="true" data-size="${size}"></div><small>${traitsAdded.length?'多出 '+traitsAdded.map(t=>TRAITS[TRAIT_INDEX[t]].name).join('、'):''}${traitsLost.length?' · 少了 '+traitsLost.map(t=>TRAITS[TRAIT_INDEX[t]].name).join('、'):''}${!traitsAdded.length&&!traitsLost.length?'结构种类相同，比例和遗传数值仍可能不同':''}</small></article></div>`:''}
 <div class="distribution-grid">${[0,1,2].map(i=>distribution(world,record,i)).join('')}</div><div class="neutral-marker"><span>中性标记 · 个体 ${record.neutralAllele===0?'A':'B'}</span><span>同源现存群体 A：${alleleA} / ${originGroup.length}</span><p>这个可遗传位点不参与功能、择偶或分类。它的比例仍可随随机变异、抽样、家系繁殖和群体变化而改变，单次变化不足以判断成因。</p></div><p class="archive-caption">分布来自起源体系 ${record.origin} 的全部现存个体；细线是所选个体的出生性状。它们不一定属于同一当前分群。</p></section>
 <section class="archive-panel"><div class="section-heading"><h2>留下的后代</h2><span class="muted">记录截至 T + ${world.tick}</span></div><p>家系通过每次真实出生延续。直接后代数量依赖观察时长与生存条件，不能单独当作跨个体的适合度排名。</p><div class="relative-grid">${parents.map(p=>individualCard(p,'亲本')).join('')}${children.slice(-4).map(c=>individualCard(c,'后代')).join('')||'<span class="muted">尚无直接后代。</span>'}</div>${children.length>4?`<details data-panel="offspring"><summary>全部 ${children.length} 个直接后代</summary><div class="offspring-links">${children.map(c=>`<button data-observe="${c.id}">#${c.id} · ${c.death?'已死亡':'存活'}</button>`).join('')}</div></details>`:''}</section>
 <section class="archive-panel"><div class="section-heading"><h2>实际能量记录</h2><span class="muted">T + ${record.born} — ${observedUntil}</span></div><div class="individual-energy">${Object.entries(energyNames).map(([key,name])=>`<article><span>${name}</span><strong>${number(energy[key])}</strong></article>`).join('')}</div><p class="archive-caption">模型能量单位。繁殖投入包含转移给后代的储备、结构及生殖消耗；初始能量与死亡转移不包含在以上消费项内。</p></section>
 <details class="archive-panel inheritance-evidence"><summary>遗传证据 · 从亲本到这副身体</summary><p>出生时记录遗传来源与数值变化，个体死亡后仍可追溯。这里的基因是简化的可遗传参数，数值按 0–100 展示。</p>${record.mode==='founder'?'<p>这是初始化生成的个体，没有亲本。初始差异来自公开的世界种子与起始设置。</p>':`<h3>生态性状</h3>${inheritanceTable(record.inheritance.genes,GENES)}<h3>形态性状</h3>${inheritanceTable(record.inheritance.shape,SHAPE_GENES)}<h3>中性位点</h3><p>来自 <button class="text-button" data-observe="${record.inheritance.neutralAllele.parent}">#${record.inheritance.neutralAllele.parent} ↗</button>，${record.inheritance.neutralAllele.before===0?'A':'B'} → ${record.neutralAllele===0?'A':'B'}，${record.inheritance.neutralAllele.mutated?'出生时发生翻转':'未发生变异'}。</p><h3>结构继承与改变</h3><div class="structure-evidence">${record.inheritance.traits.map(t=>`<span>${TRAITS[TRAIT_INDEX[t.id]].name} · ${(t.parents.length?t.parents.map(id=>'#'+id).join(' / '):'出生变异')} · ${t.retained?'保留':'未保留'}</span>`).join('')||'<span>亲本没有遗传结构。</span>'}</div><details><summary>出生变更原始记录 · ${record.inheritance.changes.length} 项</summary><pre class="raw-evidence">${escape(JSON.stringify(record.inheritance.changes,null,2))}</pre></details>`}</details>`;
}

export function snapshotView(state){
 const snapshot=state.snapshot,results=state.results;
 const complete=results?results.filter(r=>r.control.tick-r.start===r.requestedSteps&&r.altered.tick-r.start===r.requestedSteps):[];
 const metrics=[['population','存活个体'],['births','期间出生'],['deaths','期间死亡'],['biomass','身体能量库存']];
 return `<section class="archive-panel snapshot-panel"><div class="section-heading"><h2>世界的另一种可能</h2><button class="button subtle" data-checkpoint>保存当前快照</button></div><p>从同一时刻比较一个环境变化。原世界继续自己的历史，对照在独立分支中运行。</p>${snapshot?`<div class="checkpoint-meta"><span>${escape(snapshot.seed)} / T + ${snapshot.tick}</span><span>${snapshot.population} 个体 · ${number(snapshot.bytes/1048576,1)} MB</span></div><div class="comparison-controls"><select id="comparison-change" aria-label="分支中的环境变化" ${state.busy?'disabled':''}>${Object.entries(COMPARISON_CHANGES).map(([id,c])=>`<option value="${id}" ${state.change===id?'selected':''}>${c.name}</option>`).join('')}</select><button class="button primary" data-compare ${state.busy?'disabled':''}>${state.busy?`计算中 · ${state.completed}/3`:'运行独立对照 ↗'}</button>${state.busy?'<button class="text-button" data-cancel-comparison>停止计算</button>':''}</div><p class="archive-caption">3 次配对重复，每次推进 600 时步。每对分支共享环境随机状态，生物随机过程在重复间改变，外部环境沿同一随机路径演进；这是模型内的少量探索结果。</p>`:'<p class="archive-caption">快照记录当前的生命、资源、环境与随机状态。对照入口始终可选。</p>'}${state.error?`<p class="warning">${escape(state.error)}</p>`:''}
 ${results?`<div class="comparison-results"><p>完成相同 600 时步观察：${complete.length} / ${results.length} 对。${complete.length?'下表只纳入完整配对。':'尚无完整配对，无法比较同一观察窗口的结果。'}</p>${complete.length?`<div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>观测量</th><th>原环境 · 均值 [范围]</th><th>改变后 · 均值 [范围]</th></tr></thead><tbody>${metrics.map(([key,label])=>`<tr><td>${label}</td>${['control','altered'].map(side=>{const r=summarizeComparisons(complete,key,side);return `<td>${number(r.mean,1)} <small>[${number(r.min,1)}, ${number(r.max,1)}]</small></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:''}<p>${results.some(r=>r.control.saturated||r.altered.saturated)?'有分支触及计算容量而提前停止，各次观察终点不同；请在导出结果中核对时刻。':'每条分支均完成指定的观察时长。'}${results.some(r=>r.control.extinct||r.altered.extinct)?'部分分支发生了全体灭绝。':''} 此结果只说明这份快照与这些随机过程下的差异，不能推广为所有环境中的规律。</p><p class="archive-caption">实际推进时长（原环境 / 改变后）：${results.map((r,i)=>`第 ${i+1} 次 ${r.control.tick-r.start} / ${r.altered.tick-r.start}`).join('；')} 时步。</p><button class="text-button" data-export-comparison>导出全部配对结果与设置 ↗</button></div>`:''}</section>`;
}
